// Whether the word is a keyword of the language.
// 0x1001caf0 ?IsKeyword@@YAHPADH@Z
static int IsKeyword(char *text, int)
{
    int keyword = 0;
    MfAiCompiler *compiler;
    if (MfInterfaceRegistry::GetInterface("PiccoloCompilerI", (MfAi **)&compiler)) {
        MfString word(text);
        keyword = compiler->PiccoloLookupKeyword(word);
        compiler->Release();
    }
    return keyword;
}

